package com.andye.warmod.antiair.client;
import com.andye.warmod.antiair.AntiAirFlightPhase;import com.andye.warmod.icbm.client.render.IcbmLongRangeRenderContext;import java.util.*;import net.minecraft.world.phys.Vec3;
public final class AntiAirTrailSampler{public record Sample(Vec3 position,float age,float width,float alpha){}private AntiAirTrailSampler(){}public static List<Sample> sample(AntiAirVisualState state,long gameTime,double partial,IcbmLongRangeRenderContext.Lod lod){int count=switch(lod){case NEAR->26;case MEDIUM->14;case FAR->6;case EXTREME->3;};double history=state.phase()==AntiAirFlightPhase.INTERCEPT?14.0:24.0;ArrayList<Sample> result=new ArrayList<>(count);for(int i=0;i<count;i++){float age=i/(float)Math.max(1,count-1);Vec3 position=state.position(gameTime,partial-age*history);if(!position.isFinite())continue;float density=state.phase()==AntiAirFlightPhase.INTERCEPT?.52F:1F;result.add(new Sample(position,age,(.045F+age*.24F)*density,(1-age)*density));}return List.copyOf(result);}}
